<template><main><div ref="scroll" class="messages"><div class="inner"><div v-if="messages.length===0" class="empty"><b>开始一段对话</b><span>消息将发送给当前选中的模型</span></div><div v-if="notice" class="notice">{{notice}}</div><MessageItem v-for="m in messages" :key="m.id" :message="m"/></div></div><Composer/></main></template>
<script setup lang="ts">import { nextTick,ref,watch } from 'vue';import { storeToRefs } from 'pinia';import { useChatStore } from '../stores/chat';import Composer from './Composer.vue';import MessageItem from './MessageItem.vue';const chat=useChatStore();const {messages,notice}=storeToRefs(chat);const scroll=ref<HTMLDivElement>();watch(messages,async()=>{await nextTick();if(scroll.value)scroll.value.scrollTop=scroll.value.scrollHeight},{deep:true})</script>
<style scoped>main{flex:1;min-width:0;display:flex;flex-direction:column;overflow:hidden}.messages{flex:1;overflow:auto;padding:24px 20px 8px}.inner{max-width:760px;margin:auto}.empty{text-align:center;padding-top:76px}.empty b{display:block;font-size:18px;margin-bottom:8px}.empty span{color:var(--muted);font-size:13px}.notice{font-size:12px;color:var(--err);background:#fff4f6;padding:8px 10px;border-radius:8px;margin-bottom:12px}</style>
